import{_ as a,a0 as l,w as s,s as p,ao as d,I as o,x as t,a1 as r,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"使用 GSConnect 將 Android 手機連接到 Fedora 系統 | LCTT x X-CMD","titleTemplate":false,"description":"使用 GSConnect 將 Android 手機連接到 Fedora 系統 | LCTT (202002) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 GSConnect 將 Android 手機連接到 Fedora 系統 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 GSConnect 將 Android 手機連接到 Fedora 系統 | LCTT (202002) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202002/20200207 Connect Fedora to your Android phone with GSConnect","title":"使用 GSConnect 將 Android 手機連接到 Fedora 系統","tag":"202002","desc":""},"relativePath":"202002/20200207 Connect Fedora to your Android phone with GSConnect.md","filePath":"[post].md"}'),u={name:"202002/20200207 Connect Fedora to your Android phone with GSConnect.md"};function g(f,n,m,C,S,b){const e=l("Link");return s(),p("div",null,[n[32]||(n[32]=d('<h1 id="使用-gsconnect-將-android-手機連接到-fedora-系統" tabindex="-1">使用 GSConnect 將 Android 手機連接到 Fedora 系統 <a class="header-anchor" href="#使用-gsconnect-將-android-手機連接到-fedora-系統" aria-label="Permalink to “使用 GSConnect 將 Android 手機連接到 Fedora 系統”">​</a></h1><p><img src="https://fedoramagazine.org/wp-content/uploads/2019/12/gsconnect-816x345.jpg" alt=""></p><p>蘋果和微軟公司都不同程度的提供了桌面產品與移動設備集成。Fedora 提供了類似甚至更高集成度的工具——GSConnect。它可以讓你將安卓手機和你的 Fedora 桌面配對並使用。請繼續閲讀，以瞭解更多關於它的情況以及它是如何工作的信息。</p><h3 id="gsconnect-是什麼" tabindex="-1">GSConnect 是什麼? <a class="header-anchor" href="#gsconnect-是什麼" aria-label="Permalink to “GSConnect 是什麼?”">​</a></h3><p>GSConnect 是針對 GNOME 桌面定製的 KDE Connect 程序。KDE Connect 可以使你的設備能夠互相通信。但是，在 Fedora 默認的 GNOME 桌面上安裝它需要安裝大量的 KDE 依賴。</p><p>GSConnect 是一個 KDE Connect 的完整實現，其以 GNOME shell 的拓展形式出現。安裝後，GSConnect 允許你執行以下操作及更多：</p><ul><li>在計算機上接收電話通知並回覆信息</li><li>用手機操縱你的桌面</li><li>在不同設備之間分享文件與鏈接</li><li>在計算機上查看手機電量</li><li>讓手機響鈴以便你能找到它</li></ul><h3 id="設置-gsconnect-擴展" tabindex="-1">設置 GSConnect 擴展 <a class="header-anchor" href="#設置-gsconnect-擴展" aria-label="Permalink to “設置 GSConnect 擴展”">​</a></h3><p>設置 GSConnect 需要安裝兩個組件：計算機上的 GSConnect 擴展和 Android 設備上的 KDE Connect 應用。</p>',9)),o("p",null,[n[2]||(n[2]=t("首先，從 GNOME Shell 擴展網站上安裝 ",-1)),r(e,{href:"https://extensions.gnome.org/extension/1319/gsconnect/"},{default:i(()=>[...n[0]||(n[0]=[t("GSConnect",-1)])]),_:1}),n[3]||(n[3]=t(" 擴展。（Fedora Magazine 有一篇關於",-1)),r(e,{href:"https://fedoramagazine.org/install-gnome-shell-extension/"},{default:i(()=>[...n[1]||(n[1]=[t("如何安裝 GNOME Shell 擴展",-1)])]),_:1}),n[4]||(n[4]=t("的文章，可以幫助你完成這一步。）",-1))]),o("p",null,[n[7]||(n[7]=t("KDE Connect 應用程序可以在 Google 的 ",-1)),r(e,{href:"https://play.google.com/store/apps/details?id=org.kde.kdeconnect_tp"},{default:i(()=>[...n[5]||(n[5]=[t("Play 商店",-1)])]),_:1}),n[8]||(n[8]=t("上找到。它也可以在 FOSS Android 應用程序庫 ",-1)),r(e,{href:"https://f-droid.org/en/packages/org.kde.kdeconnect_tp/"},{default:i(()=>[...n[6]||(n[6]=[t("F-Droid",-1)])]),_:1}),n[9]||(n[9]=t(" 上找到。",-1))]),n[33]||(n[33]=d('<p>一旦安裝了這兩個組件，就可以配對兩個設備。安裝擴展後它在你的系統菜單中顯示為“<ruby>移動設備<rt>Mobile Devices</rt></ruby>”。單擊它會出現一個下拉菜單，你可以從中訪問“<ruby>移動設置<rt>Mobile Settings</rt></ruby>”。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2020/01/within-the-menu-1024x576.png" alt=""></p><p>你可以在這裏用 GSConnect 查看並管理已配對的設備。進入此界面後，需要在 Android 設備上啓動應用程序。</p><p>你可以在任意一台設備上進行配對初始化，在這裏我們從 Android 設備連接到計算機。點擊應用程序上的“刷新”，只要兩個設備都在同一個無線網絡環境中，你的 Android 設備便可以搜索到你的計算機。現在可以向桌面發送配對請求，並在桌面上接受配對請求以完成配對。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2020/01/pair-request-1024x576.png" alt=""></p><h3 id="使用-gsconnect" tabindex="-1">使用 GSConnect <a class="header-anchor" href="#使用-gsconnect" aria-label="Permalink to “使用 GSConnect”">​</a></h3><p>配對後，你將需要在 Android 設備授予權限，才能使用 GSConnect 上提供的許多功能。單擊設備列表中的已配對設備，便可以查看所有可用功能，並根據你的偏好和需要啓用或禁用它們。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2020/01/permissions-1024x576.png" alt=""></p><p>請記住，你還需要在這個 Android 應用程序中授予相應的權限才能使用這些功能。啓用權限後，你現在可以訪問桌面上的移動聯繫人，獲得消息通知並回復消息，甚至同步桌面和 Android 設備的剪貼板。</p><h3 id="將你的瀏覽器與-文件-應用集成" tabindex="-1">將你的瀏覽器與“文件”應用集成 <a class="header-anchor" href="#將你的瀏覽器與-文件-應用集成" aria-label="Permalink to “將你的瀏覽器與“文件”應用集成”">​</a></h3><p>GSConnect 允許你直接從計算機上的文件資源管理器的關聯菜單向 Android 設備發送文件。</p><p>在 Fedora 的默認 GNOME 桌面上，你需要安裝 <code>nautilus-python</code> 依賴包，以便在關聯菜單中顯示配對的設備。安裝此命令非常簡單，只需要在你的首選終端運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install nautilus-python</span></span></code></pre></div><p>完成後，將在“<ruby>文件<rt>Files</rt></ruby>”應用的關聯菜單中顯示“<ruby>發送到移動設備<rt>Send to Mobile Device</rt></ruby>”選項。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2020/01/send-to-mobile-2-1024x576.png" alt=""></p>',15)),o("p",null,[n[12]||(n[12]=t("同樣，為你的瀏覽器安裝相應的 WebExtension，無論是 ",-1)),r(e,{href:"https://addons.mozilla.org/en-US/firefox/addon/gsconnect/"},{default:i(()=>[...n[10]||(n[10]=[t("Firefox",-1)])]),_:1}),n[13]||(n[13]=t(" 還是 ",-1)),r(e,{href:"https://chrome.google.com/webstore/detail/gsconnect/jfnifeihccihocjbfcfhicmmgpjicaec"},{default:i(()=>[...n[11]||(n[11]=[t("Chrome",-1)])]),_:1}),n[14]||(n[14]=t(" 瀏覽器，都可以將鏈接發送到你的 Android 設備。你可以選擇直接發送鏈接以在瀏覽器中直接打開，或將其作為短信息發送。",-1))]),n[34]||(n[34]=o("h3",{id:"運行命令",tabindex:"-1"},[t("運行命令 "),o("a",{class:"header-anchor",href:"#運行命令","aria-label":"Permalink to “運行命令”"},"​")],-1)),n[35]||(n[35]=o("p",null,"GSConnect 允許你定義命令，然後可以從遠程設備在計算機上運行這些命令。這使得你可以遠程截屏，或者從你的 Android 設備鎖定和解鎖你的桌面。",-1)),n[36]||(n[36]=o("p",null,[o("img",{src:"https://fedoramagazine.org/wp-content/uploads/2020/01/commands-1024x576.png",alt:""})],-1)),n[37]||(n[37]=o("p",null,"要使用此功能，可以使用標準的 shell 命令和 GSConnect 提供的 CLI。該項目的 GitHub 存儲庫（CLI Scripting）中提供了有關此操作的文檔。",-1)),o("p",null,[r(e,{href:"https://userbase.kde.org/KDE_Connect/Tutorials/Useful_commands"},{default:i(()=>[...n[15]||(n[15]=[t("KDE UserBase Wiki",-1)])]),_:1}),n[16]||(n[16]=t(" 有一個命令示例列表。這些例子包括控制桌面的亮度和音量、鎖定鼠標和鍵盤，甚至更改桌面主題。其中一些命令是針對 KDE Plasma 設計的，需要進行修改才能在 GNOME 桌面上運行。",-1))]),n[38]||(n[38]=o("h3",{id:"探索並享受樂趣",tabindex:"-1"},[t("探索並享受樂趣 "),o("a",{class:"header-anchor",href:"#探索並享受樂趣","aria-label":"Permalink to “探索並享受樂趣”"},"​")],-1)),n[39]||(n[39]=o("p",null,"GSConnect 使我們能夠享受到極大的便利和舒適。深入研究首選項，查看你可以做的所有事情，靈活的使用這些命令功能發揮創意，並在下面的評論中自由分享你解鎖的新方式。",-1)),n[40]||(n[40]=o("hr",null,null,-1)),o("p",null,[n[18]||(n[18]=t("via: ",-1)),r(e,{href:"https://fedoramagazine.org/connect-fedora-to-your-android-phone-with-gsconnect/"},{default:i(()=>[...n[17]||(n[17]=[t("https://fedoramagazine.org/connect-fedora-to-your-android-phone-with-gsconnect/",-1)])]),_:1})]),o("p",null,[n[23]||(n[23]=t("作者：",-1)),r(e,{href:"https://fedoramagazine.org/author/lowkeyskywalker/"},{default:i(()=>[...n[19]||(n[19]=[t("Lokesh Krishna",-1)])]),_:1}),n[24]||(n[24]=t(" 選題：",-1)),r(e,{href:"https://github.com/lujun9972"},{default:i(()=>[...n[20]||(n[20]=[t("lujun9972",-1)])]),_:1}),n[25]||(n[25]=t(" 譯者：",-1)),r(e,{href:"https://github.com/chai-yuan"},{default:i(()=>[...n[21]||(n[21]=[t("chai-yuan",-1)])]),_:1}),n[26]||(n[26]=t(" 校對：",-1)),r(e,{href:"https://github.com/wxy"},{default:i(()=>[...n[22]||(n[22]=[t("wxy",-1)])]),_:1})]),o("p",null,[n[29]||(n[29]=t("本文由 ",-1)),r(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...n[27]||(n[27]=[t("LCTT",-1)])]),_:1}),n[30]||(n[30]=t(" 原創編譯，",-1)),r(e,{href:"https://linux.cn/"},{default:i(()=>[...n[28]||(n[28]=[t("Linux中國",-1)])]),_:1}),n[31]||(n[31]=t(" 榮譽推出",-1))])])}const k=a(u,[["render",g]]);export{x as __pageData,k as default};
